def seed_scenetags_and_backfill(apps, schema_editor):
    """播种 3 个用途标签 + 存量题目全打满三标签（行为不变，向后兼容）。"""
    SceneTag = apps.get_model("questions", "SceneTag")
    Question = apps.get_model("questions", "Question")
    tags = {}
    for code, name in SCENE_SEEDS:
        tag, _ = SceneTag.objects.get_or_create(code=code, defaults={"name": name})
        tags[code] = tag
    for q in Question.objects.iterator():
        existing = set(q.scenes.values_list("code", flat=True))
        missing = [t for c, t in tags.items() if c not in existing]
        if missing:
            q.scenes.add(*missing)


